function Mark() {
  return <div className="sampraan-mark" aria-label="SAMPRAAN mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M12 2l7 4v6c0 4.4-3 8.4-7 10-4-1.6-7-5.6-7-10V6z"/><path d="M12 7v6"/><circle cx="12" cy="15.4" r="1.6"/></svg></div>;
}
function Wordmark({ compact = false }: { compact?: boolean }) {
  return <div className="wordmark"><Mark /><div><b>SAMPRAAN</b><small>Secure Asset Management, Provenance, RBAC And Identity On-chain Network</small></div></div>;
}
function Status({ children, tone = "mint" }: { children: React.ReactNode; tone?: Tone }) { return <span className={`status ${signalTone[tone]}`}><i />{children}</span>; }
function Eyebrow({ children, bar = false }: { children: React.ReactNode; bar?: boolean }) { return <div className="eyebrow">{children}{bar && <span className="eyebrow-bar" />}</div>; }
function Action({ children, kind = "outline", onClick, disabled, type = "button", title }: { children: React.ReactNode; kind?: "outline" | "solid" | "text"; onClick?: () => void; disabled?: boolean; type?: "button" | "submit"; title?: string }) { return <button type={type} className={`action ${kind}`} onClick={onClick} disabled={disabled} title={title} aria-busy={disabled || undefined}>{children}</button>; }
function ThemeToggle({ compact = false }: { compact?: boolean }) { const { theme, toggleTheme } = useTheme(); return <button className={`theme-toggle ${compact ? "compact" : ""}`} onClick={toggleTheme} aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} mode`} title={`Switch to ${theme === "dark" ? "light" : "dark"} mode`}>{theme === "dark" ? <Sun size={15} /> : <Moon size={15} />}<span>{compact ? "" : theme === "dark" ? "LIGHT" : "DARK"}</span></button>; }
function BackendStatus() { const { data, isPending, isError } = trpc.health.useQuery(undefined, { refetchInterval: 30000, retry: 1 }); const status = isError ? "OFFLINE" : data?.api === "OK" ? "ONLINE" : isPending ? "CHECKING" : "DEGRADED"; const detail = isError ? "Backend unreachable — retrying automatically" : data ? `API ${data.api} · DATABASE ${data.database} · CHAIN ${data.blockchain.mode}` : "Contacting managed backend"; return <span className={`backend-status ${status.toLowerCase()}`} title={`Managed SAMPRAAN backend status: ${detail}`} role="status" aria-live="polite"><i />{status}</span>; }
function Chakra({ className = "utility-chakra" }: { className?: string }) { return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.4" className={className} aria-hidden="true"><circle cx="12" cy="12" r="9.5" /><circle cx="12" cy="12" r="2" fill="currentColor" stroke="none" />{Array.from({ length: 12 }).map((_, i) => { const a = (i * 30 * Math.PI) / 180; return <line key={i} x1={12 + 2.6 * Math.cos(a)} y1={12 + 2.6 * Math.sin(a)} x2={12 + 9.2 * Math.cos(a)} y2={12 + 9.2 * Math.sin(a)} strokeLinecap="round" />; })}</svg>; }

