function ChainChip() { const { data: chain } = useBlockchainStatus(); const online = chain?.connected ?? false; return <span className="gov-chain" title={chain ? `${chain.network} · block ${chain.latestBlock}` : "Contacting chain"}><i />{online && chain ? <span className="gov-chain-meta"><b>BESU ONLINE</b><small>#{chain.latestBlock.toLocaleString()}</small></span> : <b>{chain ? chain.mode : "…"}</b>}</span>; }
function GovHeader({ page, setPage, mobileOpen, setMobileOpen, onSignIn }: { page?: string; setPage?: (p: string) => void; mobileOpen?: boolean; setMobileOpen?: (v: boolean) => void; onSignIn?: () => void }) {
  const { user, logout } = useAuth();
  const { data: identities } = useIdentities();
  const { data: observatory } = useObservatory();
  const openAlerts = observatory?.openAlertCount ?? 0;
  const myIdentity = user ? identities?.find(item => item.linkedUserId === user.id) : undefined;
  const roleLabel = user ? (user.role === "admin" ? "ADMIN" : (myIdentity?.roles?.[0] ?? "USER").toUpperCase()) : null;
  const didLabel = myIdentity ? shortDid(myIdentity.did, 12) : user ? "SESSION VERIFIED" : null;
  const name = myIdentity?.displayName ?? user?.name ?? user?.email ?? "";
  const navTarget = (label: string) => {
    if (setPage) { setPage(label); return; }
    document.getElementById(label === "Overview" ? "top" : "capabilities")?.scrollIntoView({ behavior: "smooth" });
  };
  return <>
    <header className="gov-header"><div className="gov-header-inner">
      <div className="gov-brand"><Wordmark compact /><span className="gov-badge">BEL Prototype</span></div>
      <nav className="gov-nav" aria-label="Primary">
        {NAV_MAIN.map(label => <button key={label} className={page === label ? "active" : ""} onClick={() => navTarget(label)} aria-current={page === label ? "page" : undefined}>{label === "Audit Evidence" ? "Audit" : label === "Intelligence" ? "Security Intelligence" : label}</button>)}
      </nav>
      <div className="gov-header-actions">
        <ChainChip />
        {user ? <>
          <span className="gov-user" title={`${name} · ${didLabel ?? ""}`}>
            <Fingerprint />
            <span className="gov-user-meta"><span>DID: {didLabel}</span><b>Role: {roleLabel}</b></span>
            <ChevronDown className="chev" size={13} />
          </span>
          <button className="gov-logout" onClick={() => logout()} aria-label="Sign out (revokes server-side session)"><LogOut size={14} /> Logout</button>
        </> : <><span className="gov-avatar" aria-hidden="true"><User size={15} /></span><button className="gov-signin" onClick={() => (onSignIn ? onSignIn() : navTarget("Overview"))}>Sign In <ArrowRight size={14} /></button></>}
        <button className="gov-menu-btn" aria-label="Toggle navigation" onClick={() => setMobileOpen?.(!mobileOpen)}>{mobileOpen ? <X size={18} /> : <Menu size={18} />}</button>
      </div>
    </div></header>
    <div className={`gov-mobile-nav ${mobileOpen ? "open" : ""}`}>{NAV_MAIN.map(label => <button key={label} className={page === label ? "active" : ""} onClick={() => { navTarget(label); setMobileOpen?.(false); }}>{label === "Audit Evidence" ? "Audit" : label === "Intelligence" ? "Security Intelligence" : label}</button>)}</div>
  </>;
}

