  const rolesMutation = trpc.identities.assignRoles.useMutation({ onSuccess: result => { setShowRoles(false); invalidate(); toast.success("Roles updated", { description: `Roles set to ${result.roles.join(", ")}. Effective on the next operation.` }); }, onError: error => toast.error("Role assignment failed", { description: error.message }) });
