function AccessPage() { const { isAuthenticated, user } = useAuth(); const { data: assets, isLoading: assetsLoading } = useAssets(); const { data: identities } = useIdentities(); const { data: policies } = trpc.policies.list.useQuery(undefined, { enabled: isAuthenticated, retry: 1 }); const utils = trpc.useUtils(); const [decision, setDecision] = useState<{ decision: "ALLOW" | "DENY" | "CHALLENGE"; reason: string; policyId?: string; decisionId: string; timestamp: string; custodyUnchanged?: boolean; transaction: { transactionHash: string; blockNumber: number; status: "CONFIRMED" | "FAILED"; blockHash?: string; contractAddress?: string; from?: string; to?: string; gasUsed?: number } | null } | null>(null); const [dryRun, setDryRun] = useState<{ decision: "ALLOW" | "DENY" | "CHALLENGE"; reason: string; actor: { identity: { displayName: string; status: string } | null; roles: string[]; permissions: string[] }; ownerStatus: string; contractChecks: { check: string; note: string }[] } | null>(null); const [decisionError, setDecisionError] = useState<string | null>(null); const [assetId, setAssetId] = useState<string>(""); const [recipientId, setRecipientId] = useState<string>(""); const asset = assets?.find(a => a.id === assetId) ?? assets?.find(a => a.status === "ACTIVE") ?? assets?.[0]; const actor = user ? identities?.find(item => item.linkedUserId === user.id) : undefined; const recipient = recipientId ? identities?.find(i => i.id === recipientId) : undefined; const actorRoles = actor?.roles ?? []; const transfer = trpc.assets.authorizeTransfer.useMutation({ onSuccess: result => { setDecision(result); setDecisionError(null); toast[result.decision === "ALLOW" ? "success" : result.decision === "DENY" ? "error" : "warning"](`Backend decision: ${result.decision}`, { description: result.reason }); void utils.audit.invalidate(); void utils.assets.invalidate(); void utils.observatory.invalidate() }, onError: error => { setDecisionError(error.message); setDecision(null); toast.error("Authorization request failed", { description: error.message }) } }); const dryRunMutation = trpc.policies.evaluateTransfer.useMutation({ onSuccess: result => { setDryRun(result); toast[result.decision === "ALLOW" ? "success" : result.decision === "DENY" ? "error" : "warning"](`Dry-run: ${result.decision}`, { description: `${result.reason} — no chain submission.` }); void utils.audit.invalidate() }, onError: error => toast.error("Dry-run failed", { description: error.message }) }); const evaluate = () => { if (!asset) { toast.warning("No registered asset available", { description: "Register an asset from the Assets registry first." }); return } if (!isAuthenticated) { toast.info("Secure login required", { description: "The backend authorization boundary will evaluate this request after session authentication." }); return } transfer.mutate({ assetId: asset.id, recipientIdentityId: recipientId || undefined }) }; const runDry = () => { if (!asset) { toast.warning("No registered asset available", { description: "Register an asset first." }); return } if (!isAuthenticated) { toast.info("Sign-in required", { description: "The dry-run evaluates the CURRENT session actor server-side." }); return } dryRunMutation.mutate({ assetId: asset.id }) }; const decisionClass = decision ? decision.decision === "DENY" ? "deny" : decision.decision === "CHALLENGE" ? "challenge" : "allow" : "standby"; const activePolicies = (policies ?? []).filter(p => p.active); return <div className="special-page"><div className="special-heading"><div><Eyebrow>TRUST FABRIC / POLICY ENGINE</Eyebrow><h1>Authorization Control</h1><p>Make the decision legible before the transaction is executed.</p></div><Status tone={decisionError ? "red" : transfer.isPending ? "amber" : "mint"}>{decisionError ? "REQUEST FAILED" : transfer.isPending ? "EVALUATING" : decision ? "DECISION RECORDED" : "POLICY ENGINE ACTIVE"}</Status></div>
    <div className="auth-workspace"><div className="auth-column"><PanelHead eyebrow="ACTOR (SERVER-RESOLVED)" title="Who is acting?" /><InfoRow label="DID" value={actor ? shortDid(actor.did) : user ? "session without SAMPRAAN identity" : "unauthenticated"} mono /><InfoRow label="IDENTITY ROLES" value={actor?.roles?.length ? actor.roles.join(" + ") : "none assigned"} /><InfoRow label="PLATFORM" value={user ? user.role === "admin" ? "ADMIN" : "USER" : "—"} /><InfoRow label="ORGANIZATION" value={actor?.organization ?? "—"} /><InfoRow label="CONTEXT" value={isAuthenticated ? "Authenticated session" : "Unauthenticated"} status={isAuthenticated ? "mint" : "amber"} />{actor && <div className="evidence-block"><h4>EFFECTIVE PERMISSIONS</h4><div className="decision-proof">{actorRoles.length ? actorRoles.map(p => <div key={p}><span>{p.split(":")[0]}</span><code>{p}</code></div>) : <div><span>—</span><code>no domain permissions on this identity</code></div>}</div></div>}</div>
      <div className="auth-column request"><PanelHead eyebrow="REQUEST" title="What is being asked?" /><div className="sampraan-field"><label className="sampraan-label" htmlFor="ac-asset">ASSET</label><select id="ac-asset" className="sampraan-select" value={asset?.id ?? ""} onChange={e => setAssetId(e.target.value)}>{(assets ?? []).map(a => <option key={a.id} value={a.id}>{a.assetId} · {a.name} ({a.classification})</option>)}</select></div><div className="sampraan-field"><label className="sampraan-label" htmlFor="ac-recipient">RECIPIENT CUSTODIAN (OPTIONAL — DEFAULT: ACTOR)</label><select id="ac-recipient" className="sampraan-select" value={recipientId} onChange={e => setRecipientId(e.target.value)}><option value="">Acting identity (self)</option>{(identities ?? []).filter(i => i.status === "ACTIVE").map(i => <option key={i.id} value={i.id}>{i.displayName} · {shortDid(i.did)}</option>)}</select></div><InfoRow label="ACTION" value="Transfer custody" /><InfoRow label="SENSITIVITY" value={asset ? `${asset.classification.replaceAll("_", " ").toLowerCase()} sensitivity` : "—"} status={asset?.classification === "HIGHLY_SENSITIVE" || asset?.classification === "CRITICAL" ? "amber" : "mint"} /><InfoRow label="RECIPIENT" value={recipient ? recipient.displayName : "Acting identity"} status={recipient ? (recipient.status === "ACTIVE" ? "mint" : "red") : "muted"} /></div>
      <div className="decision-column"><Eyebrow>FINAL DECISION</Eyebrow><div className={`decision-big ${decisionClass}`}>{decision?.decision === "DENY" ? <X size={23} /> : decision?.decision === "CHALLENGE" ? <Clock3 size={23} /> : <Check size={23} />}<strong>{decision ? decisionLabel(decision.decision) : "STANDBY"}</strong><span>{decision ? decision.decision === "ALLOW" ? "POLICY CONDITIONS SATISFIED" : decision.decision === "DENY" ? "POLICY CONDITIONS FAILED" : "STEP-UP REQUIRED" : "AWAITING EVALUATION"}</span></div><div className="why-box"><Eyebrow>WHY?</Eyebrow>{[["ROLE", actor?.roles?.[0] ?? "NO IDENTITY ROLE", decision ? decision.decision === "ALLOW" ? "mint" : "red" : "muted"], ["RESOURCE", asset?.name ?? "—", "mint"], ["ACTION", "TRANSFER", "mint"], ["CLASSIFICATION", asset?.classification ?? "—", "amber"]].map(([a, b, t]) => <div key={a}><span>{a}</span><b>{String(b)}</b><Status tone={t as Tone}>{decision ? t === "mint" ? "MATCH" : t === "red" ? "FAIL" : "REVIEW" : "PENDING"}</Status></div>)}</div>
        {dryRun && <div className="evidence-block"><h4>DRY-RUN EXPLANATION — {dryRun.decision}</h4><p className="panel-note">{dryRun.reason}</p><ul className="sampraan-checklist">{dryRun.contractChecks.map(check => <li key={check.check} className={dryRun.decision === "ALLOW" ? "" : "fail"}><span>▸</span><span><b>{check.check}</b> — {check.note}</span></li>)}</ul><div className="decision-proof"><div><span>ACTOR ROLES</span><code>{dryRun.actor.roles.join(", ") || "none"}</code></div><div><span>ACTOR PERMS</span><code>{dryRun.actor.permissions.join(", ") || "none"}</code></div><div><span>OWNER STATUS</span><code>{dryRun.ownerStatus}</code></div></div></div>}
        {decision && <div className="why-box decision-proof"><Eyebrow>DECISION PROOF</Eyebrow><div><span>DECISION ID</span><code>{decision.decisionId}</code></div><div><span>POLICY</span><code>{decision.policyId ?? "— / ROLE PERMISSION EVALUATION"}</code></div><div><span>TIMESTAMP</span><code>{formatTimestamp(decision.timestamp)}</code></div><div><span>CHAIN ANCHOR</span><code>{decision.transaction?.status === "CONFIRMED" && decision.transaction.transactionHash ? `${shortDid(decision.transaction.transactionHash, 8)} / #${decision.transaction.blockNumber?.toLocaleString() ?? "—"}` : decision.custodyUnchanged ? "ALREADY IN CUSTODY — NO TRANSFER NEEDED" : "OFF CHAIN — DENIED BEFORE EXECUTION"}</code></div></div>}
        {decisionError && <p className="panel-note" role="alert">Authorization request failed: {decisionError}. The policy engine could not evaluate this request — retry or verify the session.</p>}
        <Action kind="solid" disabled={transfer.isPending || assetsLoading} onClick={evaluate} title={isAuthenticated ? "Submit a real TRANSFER request: policy engine → smart contract → Besu" : "Sign in to submit a real authorization request"}>{transfer.isPending ? "EVALUATING POLICY…" : isAuthenticated ? "REQUEST TRANSFER VIA BACKEND" : "TRANSFER (SIGN-IN REQUIRED)"} <ArrowRight size={15} /></Action><Action disabled={dryRunMutation.isPending} onClick={runDry} title="Explain the decision the engine WOULD make — no chain submission">{dryRunMutation.isPending ? "ANALYZING…" : "DRY-RUN / EXPLAIN"} <Terminal size={15} /></Action>
        {activePolicies.length > 0 && <div className="evidence-block"><h4>POLICY CATALOG ({activePolicies.length} ACTIVE)</h4><div className="sampraan-table-wrap"><table className="sampraan-table"><thead><tr><th>POLICY</th><th>SUBJECT / RESOURCE / ACTION</th><th>CLASSIFICATION</th><th>EFFECT</th></tr></thead><tbody>{activePolicies.map(p => <tr key={p.id}><td>{p.name}</td><td>{p.subjectRole ?? "any"} / {p.resourceType ?? "asset"} / {p.action ?? "transfer"}</td><td>{p.assetClassification ?? "any"}</td><td><Status tone={decisionTone(p.effect === "DENY" ? "DENY" : p.effect === "CHALLENGE" ? "CHALLENGE" : "ALLOW")}>{p.effect}</Status></td></tr>)}</tbody></table></div><p className="panel-note">The deterministic engine in authorization.service.ts is the source of truth; this catalog documents its high-sensitivity guard. Contract checks always re-verify on-chain.</p></div>}
      </div></div></div>;
}

function InfoRow({ label, value, mono, status }: { label: string; value: string; mono?: boolean; status?: Tone }) { return <div className="info-row"><span>{label}</span><strong className={mono ? "mono" : ""}>{value}</strong>{status && <Status tone={status}>{status === "mint" ? "MATCH" : "REVIEW"}</Status>}</div>; }
function AssetsPage() { const { isAuthenticated, user } = useAuth(); const { data: backendAssets, isLoading: assetsLoading, error: assetsError, source: assetsSource } = useAssets(); const { data: identities } = useIdentities(); const utils = trpc.useUtils(); const [query, setQuery] = useState(""); const [selectedKey, setSelectedKey] = useState<string | null>(null); const [showCreate, setShowCreate] = useState(false); const [showAssign, setShowAssign] = useState(false); const [assignTarget, setAssignTarget] = useState<string>(""); const [txDetail, setTxDetail] = useState<{ assetId: string; hash: string; block: number | null } | null>(null); const liveRows = useMemo(() => toAssetRows(backendAssets, identities), [backendAssets, identities]); const usingDemo = !liveRows.length; const rows = usingDemo ? [] : liveRows; const filtered = rows.filter(row => matchesAssetQuery(row, query)); const selected = backendAssets?.find(a => a.id === selectedKey) ?? backendAssets?.find(a => a.assetId === filtered[0]?.assetId) ?? backendAssets?.[0]; const selectedCustodian = selected && identities ? identities.find(i => i.id === selected.custodianIdentityId) : undefined; const isAdmin = user?.role === "admin"; const invalidate = () => { void utils.assets.invalidate(); void utils.observatory.invalidate(); void utils.audit.invalidate(); };
  const [form, setForm] = useState({ assetId: "", name: "", type: "", classification: "CONTROLLED", description: "", custodianIdentityId: "", integrityHash: "", status: "ACTIVE" }); const [formErrors, setFormErrors] = useState<Record<string, string>>({});
  const register = trpc.assets.create.useMutation({ onSuccess: asset => { setShowCreate(false); invalidate(); setSelectedKey(asset.id); toast.success("Asset registered", { description: asset.anchor?.outcome === "ANCHORED" ? `Minted on-chain — NFT token ${asset.tokenId ?? "assigned"} (tx ${asset.anchor.transactionHash?.slice(0, 18)}…).` : "Created in the registry. Chain anchor: " + String(asset.anchor?.outcome).toLowerCase() + " — see audit evidence." }); if (asset.anchor?.outcome === "ANCHORED" && asset.anchor.transactionHash) setTxDetail({ assetId: asset.assetId, hash: asset.anchor.transactionHash, block: asset.anchor.blockNumber ?? null }); }, onError: error => { const msg = error.message; const field = msg.toLowerCase().includes("assetid") ? "assetId" : msg.toLowerCase().includes("name") ? "name" : msg.toLowerCase().includes("type") ? "type" : msg.toLowerCase().includes("custodian") ? "custodianIdentityId" : msg.toLowerCase().includes("owner") ? "custodianIdentityId" : "form"; setFormErrors({ [field]: msg }); toast.error("Asset registration rejected", { description: msg }); } });
  const assignMutation = trpc.assets.assign.useMutation({ onSuccess: result => { setShowAssign(false); invalidate(); toast.success("Custody assigned", { description: `Confirmed on-chain in block ${result.transaction.blockNumber} (tx ${result.transaction.transactionHash.slice(0, 18)}…).` }); setTxDetail({ assetId: (selected?.assetId ?? ""), hash: result.transaction.transactionHash, block: result.transaction.blockNumber }); }, onError: error => toast.error("Assignment rejected", { description: error.message }) });
  const statusMutation = trpc.assets.setStatus.useMutation({ onSuccess: updated => { invalidate(); toast.success(`Asset ${updated.status.toLowerCase()}`, { description: updated.changed && updated.anchor?.outcome === "ANCHORED" ? `Lifecycle anchored on-chain (tx ${updated.anchor.reason?.slice(0, 18)}…)` : "Read model updated." }); }, onError: error => toast.error("Status change failed", { description: error.message }) });
  const { data: assetDetail } = trpc.assets.detail.useQuery({ assetId: selected?.id ?? "" }, { enabled: !!selected?.id && isAuthenticated && !!txDetail, retry: false });
  const submitCreate = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const errors: Record<string, string> = {}; if (form.assetId.trim().length < 2) errors.assetId = "Asset ID must be at least 2 characters"; if (form.name.trim().length < 2) errors.name = "Name must be at least 2 characters"; if (form.type.trim().length < 2) errors.type = "Type must be at least 2 characters"; if (!form.custodianIdentityId) errors.custodianIdentityId = "Select the owner / custodian identity"; setFormErrors(errors); if (Object.keys(errors).length) return; register.mutate({ assetId: form.assetId.trim(), name: form.name.trim(), type: form.type.trim(), classification: form.classification as "PUBLIC" | "CONTROLLED" | "SENSITIVE" | "HIGHLY_SENSITIVE" | "CRITICAL", description: form.description.trim() || undefined, ownerIdentityId: form.custodianIdentityId, custodianIdentityId: form.custodianIdentityId, integrityHash: form.integrityHash.trim() || undefined, status: form.status as "ACTIVE" | "PENDING" | "REVOKED" }); };
  const statusLine = assetsLoading ? "SYNCING REGISTRY…" : usingDemo ? "DEMO REGISTRY UNAVAILABLE — SIGN IN" : `${liveRows.length} ASSETS${filtered.length !== liveRows.length ? ` / ${filtered.length} SHOWN` : ""} / ${liveRows.every(row => row.statusTone === "mint") ? "ALL ACTIVE" : "REVIEW REQUIRED"}`;
  return <div className="special-page"><div className="special-heading"><div><Eyebrow>DIGITAL ASSETS / BLOCKCHAIN PROVENANCE</Eyebrow><h1>Digital Assets</h1><p>Manage digital assets and verify their blockchain provenance.</p></div><Action kind="solid" disabled={register.isPending || !isAdmin} onClick={() => { setForm(f => ({ ...f, custodianIdentityId: f.custodianIdentityId || identities?.find(i => i.status === "ACTIVE")?.id || "" })); setShowCreate(true); setFormErrors({}) }} title={isAdmin ? "Open the asset registration form (admin API)" : "Admin session required"}><Plus size={15} /> {register.isPending ? "MINTING…" : "Register Asset"}</Action></div>
    <div className="asset-table-panel"><div className="table-toolbar"><label className="table-search" htmlFor="sampraan-asset-search"><Search size={14} aria-hidden="true" /><input id="sampraan-asset-search" type="search" placeholder="Search assets" value={query} onChange={e => setQuery(e.target.value)} aria-label="Search assets by name, id, classification, or custodian" /></label><Status tone={usingDemo && !assetsLoading ? "muted" : "mint"}>{statusLine}</Status></div><div className="asset-table"><div className="asset-thead"><span>ASSET</span><span>NFT TOKEN</span><span>CLASSIFICATION</span><span>CUSTODIAN</span><span>STATUS</span><span>REGISTERED</span></div>{filtered.map(row => { const token = backendAssets?.find(a => a.assetId === row.assetId)?.tokenId; return <div className={`asset-tr${selected?.assetId === row.assetId ? " selected" : ""}`} key={row.key} onClick={() => setSelectedKey(row.key)} role="button" tabIndex={0} onKeyDown={e => { if (e.key === "Enter") setSelectedKey(row.key) }}><div><b>{row.name}</b><code>{row.assetId}</code></div><span className="status mint">{token ? `#${token}` : "NOT MINTED"}</span><span>{row.classification}</span><span>{row.custodian}</span><Status tone={row.statusTone}>{row.status}</Status><time>{row.time}</time></div>; })}{assetsLoading && !filtered.length && Array.from({ length: 3 }).map((_, i) => <div className="asset-tr row-loading" key={`loading-${i}`} aria-hidden="true"><div><b>Syncing registry…</b><code>awaiting backend</code></div><span>—</span><span>—</span><Status tone="muted">LOADING</Status><time>—</time></div>)}{!assetsLoading && !filtered.length && <div className="table-empty"><div><Eyebrow>NO MATCHING ASSETS</Eyebrow><p>{query ? `No assets match “${query}”. Clear the search to see the full registry.` : assetsSource === "live" ? "No controlled assets are registered yet. Use Register Asset to create the first record." : "Sign in to load the live asset registry."}</p>{query && <Action kind="text" onClick={() => setQuery("")}>Clear search</Action>}</div></div>}</div></div>
    {!!assetsError && <p className="panel-note" role="alert">Asset registry unavailable ({String((assetsError as { message?: string }).message ?? "network error")}). {user ? "Retry shortly." : "Sign in to load live data."}</p>}
    {selected && <div className="provenance-card"><div style={{ display: "flex", justifyContent: "space-between", gap: 14, flexWrap: "wrap", alignItems: "flex-start" }}><div><Eyebrow>SELECTED ASSET / {selected.assetId}</Eyebrow><h2>{selected.name}</h2><p>{selected.classification} · token <code>{selected.tokenId ?? "not minted"}</code> · custodian <code>{selectedCustodian?.displayName ?? "—"}</code></p></div><div style={{ display: "flex", gap: 9, flexWrap: "wrap" }}>{isAdmin && <Action onClick={() => { setAssignTarget(selected.custodianIdentityId ?? ""); setShowAssign(true) }} disabled={assignMutation.isPending}>Assign Custody</Action>}{isAdmin && selected.status !== "ACTIVE" && <Action onClick={() => statusMutation.mutate({ assetId: selected.id, status: "ACTIVE" })} disabled={statusMutation.isPending}>Activate</Action>}{isAdmin && selected.status === "ACTIVE" && <Action kind="text" onClick={() => { if (window.confirm(`Suspend ${selected.assetId}? Suspended assets are frozen on-chain.`)) statusMutation.mutate({ assetId: selected.id, status: "PENDING" }) }} disabled={statusMutation.isPending}>Suspend</Action>}</div></div>
      {assetDetail?.custody?.length ? <div className="sampraan-table-wrap" style={{ marginTop: 14 }}><table className="sampraan-table"><thead><tr><th>CUSTODY EVENT</th><th>CUSTODIAN</th><th>EVIDENCE</th><th>WHEN</th></tr></thead><tbody>{assetDetail.custody.map((c, i) => { const custodian = identities?.find(x => x.id === c.custodianIdentityId); return <tr key={c.id ?? i}><td>{c.endedAt ? "RELEASED" : "HELD"}</td><td>{custodian?.displayName ?? "—"}</td><td title={c.reason ?? undefined}>{c.reason ?? c.id}</td><td>{formatClock(c.startedAt)}</td></tr>; })}</tbody></table></div> : <p className="panel-note">No custody history rows yet — assignment/transfer operations will record evidence here.</p>}
    </div>}
    {showCreate && <div className="sampraan-dialog-overlay" role="dialog" aria-modal="true" aria-label="Register asset" onClick={e => { if (e.target === e.currentTarget) setShowCreate(false) }}><div className="sampraan-dialog"><div className="sampraan-dialog-head"><div><Eyebrow>ASSET ADMINISTRATION</Eyebrow><h2>Register controlled asset</h2></div><button className="sampraan-dialog-close" onClick={() => setShowCreate(false)} aria-label="Close"><X size={15} /></button></div><form onSubmit={submitCreate} noValidate>
      <div className="form-grid-2"><div className="sampraan-field"><label className="sampraan-label" htmlFor="as-id">ASSET ID (UNIQUE)</label><input id="as-id" className="sampraan-input" value={form.assetId} onChange={e => setForm(f => ({ ...f, assetId: e.target.value }))} placeholder="BEL-FW-2026-014" aria-invalid={!!formErrors.assetId} />{formErrors.assetId && <p className="sampraan-field-error" role="alert">{formErrors.assetId}</p>}</div><div className="sampraan-field"><label className="sampraan-label" htmlFor="as-type">TYPE</label><input id="as-type" className="sampraan-input" value={form.type} onChange={e => setForm(f => ({ ...f, type: e.target.value }))} placeholder="FIRMWARE / DOCUMENT / INSTRUMENT" aria-invalid={!!formErrors.type} />{formErrors.type && <p className="sampraan-field-error" role="alert">{formErrors.type}</p>}</div></div>
      <div className="sampraan-field"><label className="sampraan-label" htmlFor="as-name">NAME</label><input id="as-name" className="sampraan-input" value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} placeholder="Restricted Firmware Package" aria-invalid={!!formErrors.name} />{formErrors.name && <p className="sampraan-field-error" role="alert">{formErrors.name}</p>}</div>
      <div className="form-grid-2"><div className="sampraan-field"><label className="sampraan-label" htmlFor="as-class">CLASSIFICATION</label><select id="as-class" className="sampraan-select" value={form.classification} onChange={e => setForm(f => ({ ...f, classification: e.target.value }))}><option value="PUBLIC">PUBLIC</option><option value="CONTROLLED">CONTROLLED</option><option value="SENSITIVE">SENSITIVE</option><option value="HIGHLY_SENSITIVE">HIGHLY_SENSITIVE</option><option value="CRITICAL">CRITICAL</option></select></div><div className="sampraan-field"><label className="sampraan-label" htmlFor="as-status">INITIAL STATUS</label><select id="as-status" className="sampraan-select" value={form.status} onChange={e => setForm(f => ({ ...f, status: e.target.value }))}><option value="ACTIVE">ACTIVE</option><option value="PENDING">PENDING</option></select></div></div>
      <div className="sampraan-field"><label className="sampraan-label" htmlFor="as-cust">OWNER / CUSTODIAN IDENTITY</label><select id="as-cust" className="sampraan-select" value={form.custodianIdentityId} onChange={e => setForm(f => ({ ...f, custodianIdentityId: e.target.value }))} aria-invalid={!!formErrors.custodianIdentityId}>{<option value="" disabled>Select an ACTIVE identity…</option>}{(identities ?? []).filter(i => i.status === "ACTIVE").map(i => <option key={i.id} value={i.id}>{i.displayName} · {shortDid(i.did)}</option>)}</select>{formErrors.custodianIdentityId && <p className="sampraan-field-error" role="alert">{formErrors.custodianIdentityId}</p>}</div>
      <div className="sampraan-field"><label className="sampraan-label" htmlFor="as-int">INTEGRITY HASH (OPTIONAL, e.g. sha256:…)</label><input id="as-int" className="sampraan-input" value={form.integrityHash} onChange={e => setForm(f => ({ ...f, integrityHash: e.target.value }))} placeholder="sha256:…" /></div>
      <div className="sampraan-field"><label className="sampraan-label" htmlFor="as-desc">DESCRIPTION</label><textarea id="as-desc" className="sampraan-input" rows={3} value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} placeholder="What this asset represents (kept off-chain; only digests are anchored)." /></div>
      <p className="panel-note">Submission validates server-side, requires an admin session, writes the registry row, then mints the asset as a restricted ERC-721 NFT on the Besu chain. Only digests go on-chain — never document contents.</p>
      <div className="sampraan-dialog-actions"><Action type="button" onClick={() => setShowCreate(false)}>Cancel</Action><Action kind="solid" type="submit" disabled={register.isPending}>{register.isPending ? "MINTING ON-CHAIN…" : "REGISTER / MINT ASSET"}</Action></div></form></div></div>}
    {showAssign && selected && <div className="sampraan-dialog-overlay" role="dialog" aria-modal="true" aria-label="Assign custody" onClick={e => { if (e.target === e.currentTarget) setShowAssign(false) }}><div className="sampraan-dialog"><div className="sampraan-dialog-head"><div><Eyebrow>CUSTODY ASSIGNMENT</Eyebrow><h2>Assign {selected.assetId}</h2></div><button className="sampraan-dialog-close" onClick={() => setShowAssign(false)} aria-label="Close"><X size={15} /></button></div><div className="sampraan-field"><label className="sampraan-label" htmlFor="as-assign-target">NEW CUSTODIAN (must be ACTIVE on-chain)</label><select id="as-assign-target" className="sampraan-select" value={assignTarget} onChange={e => setAssignTarget(e.target.value)}>{(identities ?? []).filter(i => i.status === "ACTIVE").map(i => <option key={i.id} value={i.id}>{i.displayName} · {shortDid(i.did)}</option>)}</select></div><p className="panel-note">The smart contract independently re-verifies the operator role and that the recipient identity is registered and ACTIVE on-chain. Read model + custody history update only after confirmation.</p><div className="sampraan-dialog-actions"><Action type="button" onClick={() => setShowAssign(false)}>Cancel</Action><Action kind="solid" disabled={assignMutation.isPending || !assignTarget} onClick={() => assignMutation.mutate({ assetId: selected.id, custodianIdentityId: assignTarget })}>{assignMutation.isPending ? "SUBMITTING TO CHAIN…" : "ASSIGN CUSTODY"}</Action></div></div></div>}
    {txDetail && <div className="sampraan-dialog-overlay" role="dialog" aria-modal="true" aria-label="Transaction evidence" onClick={e => { if (e.target === e.currentTarget) setTxDetail(null) }}><div className="sampraan-dialog"><div className="sampraan-dialog-head"><div><Eyebrow>ON-CHAIN EVIDENCE</Eyebrow><h2>NFT MINTED ✓</h2></div><button className="sampraan-dialog-close" onClick={() => setTxDetail(null)} aria-label="Close"><X size={15} /></button></div><div className="evidence-block"><h4>{txDetail.assetId}</h4><div className="decision-proof"><div><span>TX HASH</span><code>{txDetail.hash}</code></div><div><span>BLOCK</span><code>#{txDetail.block?.toLocaleString() ?? "pending"}</code></div><div><span>NETWORK</span><code>SAMPRAAN-LOCAL-QBFT / CHAIN ID 4224</code></div><div><span>EVIDENCE</span><code>QBFT immediate finality — receipt retrievable by hash</code></div></div></div><div className="sampraan-dialog-actions"><Action kind="solid" onClick={() => setTxDetail(null)}>Close</Action></div></div></div>}
  </div>;
}
function AuditPage() { const { data: events, isLoading: auditLoading, error: auditError, source: auditSource } = useAuditEvents(); const { data: identities } = useIdentities(); const utils = trpc.useUtils(); const { user } = useAuth(); const [decisionFilter, setDecisionFilter] = useState<"ALL" | "ALLOW" | "DENY" | "CHALLENGE">("ALL"); const [txInspect, setTxInspect] = useState<string | null>(null); const rows = useMemo(() => toAuditRows(events, identities), [events, identities]); const chainRows = (events ?? []).filter(ev => ev.source === "CHAIN_READ_MODEL"); const usingDemo = !rows.length; const shown = usingDemo ? [] : rows.filter(row => decisionFilter === "ALL" || row.decision === decisionLabel(decisionFilter)); const decisionCycle = () => setDecisionFilter(current => current === "ALL" ? "DENY" : current === "DENY" ? "CHALLENGE" : current === "CHALLENGE" ? "ALLOW" : "ALL"); const sourceEyebrow = usingDemo ? "EVIDENCE / DEMO STREAM" : "EVIDENCE / LIVE STREAM"; const { data: txDetail, isFetching: txLoading } = trpc.blockchain.transaction.useQuery({ transactionHash: txInspect ?? "" }, { enabled: !!txInspect && /^0x[0-9a-fA-F]{64}$/.test(txInspect), retry: false }); const exportEvidence = () => { if (!events?.length) { toast.warning("No evidence to export", { description: "Perform real operations first." }); return } const blob = new Blob([JSON.stringify(events, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `sampraan-audit-evidence-${Date.now()}.json`; a.click(); URL.revokeObjectURL(url); toast.success("Evidence exported", { description: `${events.length} audit record(s) exported as JSON (metadata only, no secrets).` }); };
  const copyHash = (hash: string) => { void navigator.clipboard?.writeText(hash); toast.success("Transaction hash copied"); };
  return <div className="special-page"><div className="special-heading"><div><Eyebrow>TRUST FABRIC / {sourceEyebrow}</Eyebrow><h1>Audit Evidence</h1><p>Forensic visibility into every identity, policy, asset, and chain event.</p></div><Action onClick={exportEvidence} title="Export the current live evidence stream as JSON"><Terminal size={15} /> Export evidence</Action></div><div className="filter-row"><button type="button" onClick={decisionCycle} className={decisionFilter !== "ALL" ? "active" : ""} title="Cycle the decision filter across the recorded evidence">Decision: {decisionFilter === "ALL" ? "ALL" : decisionLabel(decisionFilter)}<ChevronDown size={12} /></button><button type="button" className={chainRows.length ? "active" : ""} disabled={!chainRows.length} title="Chain-projected events come from the indexer (source=CHAIN_READ_MODEL)">On-chain events: {chainRows.length}</button>{["Actor", "DID", "Action", "Asset"].map(x => <button key={x} type="button" disabled title={`${x} filter requires a backend query scope outside the current API surface`}>{x}<ChevronDown size={12} /></button>)}</div><div className="audit-table-panel"><div className="audit-head"><span>TIMESTAMP</span><span>ACTOR / DID</span><span>ACTION</span><span>RESOURCE</span><span>DECISION</span><span>TX HASH / BLOCK</span><span>SOURCE</span></div>{shown.map(row => { const ev = (events ?? []).find(e => e.id === row.key); const onChain = ev?.source === "CHAIN_READ_MODEL" || !!ev?.transactionHash; return <div className="audit-row" key={row.key}><time title={row.fullTime}>{row.time}</time><div><b>{row.actor}</b><code>{row.did}</code></div><span>{row.action}</span><span>{row.resource}</span><Status tone={row.decisionTone}>{row.decision}</Status><code style={{ cursor: ev?.transactionHash ? "pointer" : "" }} onClick={() => ev?.transactionHash && copyHash(ev.transactionHash)} title={ev?.transactionHash ? "Inspect on-chain transaction evidence — click to copy the hash" : "No on-chain transaction for this record"}>{row.tx}</code><span className={`onchain-tag ${onChain ? "" : "off"}`} title={ev?.source === "CHAIN_READ_MODEL" ? "Projected by the chain-event indexer" : onChain ? "Confirmed on-chain — tx hash recorded" : "Off-chain application decision"}>{onChain ? "ON-CHAIN" : "OFF-CHAIN"}</span></div>; })}{auditLoading && !shown.length && Array.from({ length: 4 }).map((_, i) => <div className="audit-row row-loading" key={`loading-${i}`} aria-hidden="true"><time>—</time><div><b>Syncing evidence stream…</b><code>awaiting backend</code></div><span>—</span><span>—</span><Status tone="muted">LOADING</Status><code>—</code><span>—</span></div>)}{!auditLoading && !shown.length && <div className="table-empty"><div><Eyebrow>NO EVIDENCE RECORDED</Eyebrow><p>{usingDemo ? (user ? "No audit events recorded yet. Perform a real operation — register an identity, mint an asset, request a transfer — to generate evidence." : "Sign in to load the live evidence stream; unauthenticated visitors see no audit data.") : decisionFilter !== "ALL" ? `No events match the ${decisionLabel(decisionFilter)} decision filter. Switch back to ALL to see the full stream.` : "No audit events have been recorded yet."}</p>{decisionFilter !== "ALL" && <Action kind="text" onClick={() => setDecisionFilter("ALL")}>Show all decisions</Action>}</div></div>}</div>{!!auditError && <p className="panel-note" role="alert">Audit evidence stream unavailable ({String((auditError as { message?: string }).message ?? "network error")}). {user ? "Retry shortly." : "Sign in to load live evidence."}</p>}{auditSource === "live" && rows.length > 0 && <p className="panel-note">Showing {rows.length} live evidence record{rows.length === 1 ? "" : "s"} from the protected audit.list procedure · {chainRows.length} projected from chain events by the indexer.</p>}
    {txInspect && <div className="sampraan-dialog-overlay" role="dialog" aria-modal="true" aria-label="Transaction evidence" onClick={e => { if (e.target === e.currentTarget) setTxInspect(null) }}><div className="sampraan-dialog"><div className="sampraan-dialog-head"><div><Eyebrow>ON-CHAIN TRANSACTION DETAIL</Eyebrow><h2>Receipt evidence</h2></div><button className="sampraan-dialog-close" onClick={() => setTxInspect(null)} aria-label="Close"><X size={15} /></button></div>{txLoading ? <div className="module-record row-loading">FETCHING RECEIPT FROM BESU…</div> : txDetail ? <div className="evidence-block"><div className="decision-proof">{Object.entries(txDetail).filter(([k]) => k !== "events").map(([k, v]) => <div key={k}><span>{k.toUpperCase()}</span><code>{String(v)}</code></div>)}</div>{!!txDetail.events && Object.keys(txDetail.events).length > 0 && <><h4>CONTRACT EVENTS</h4><div className="decision-proof">{Object.entries(txDetail.events).map(([name, ev]) => <div key={name}><span>{name}</span><code>{JSON.stringify((ev as { args?: unknown }).args ?? ev)}</code></div>)}</div></>}</div> : <p className="panel-note" role="alert">Receipt not found for this hash. The chain may have restarted since the transaction — the audit record remains the evidence of the decision.</p>}<div className="sampraan-dialog-actions"><Action kind="solid" onClick={() => setTxInspect(null)}>Close</Action></div></div></div>}
  </div>;
}
function IntelligencePage() { const { data: alerts, isLoading: alertsLoading } = useSecurityAlerts(); const { data: events } = useAuditEvents(); const { data: identities } = useIdentities(); const utils = trpc.useUtils(); const { user } = useAuth(); const metrics = useMemo(() => alertMetrics(alerts), [alerts]); const scan = trpc.intelligence.scan.useMutation({ onSuccess: result => { void utils.alerts.invalidate(); void utils.audit.invalidate(); toast.success("Advisory scan complete", { description: `${result.scanned} events scanned · ${result.created} alert(s) created · ${result.suppressed} duplicate(s) suppressed.` }) }, onError: error => toast.error("Scan failed", { description: error.message }) }); const live = !!alerts?.length; const riskValue = metrics.maxRisk !== null ? String(metrics.maxRisk) : live ? "0" : "—"; const riskTone: Tone = (metrics.maxRisk ?? 0) >= 70 ? "red" : (metrics.maxRisk ?? 0) >= 40 ? "amber" : "mint"; const deniedEvents = (events ?? []).filter(ev => ev.action === "AUTHORIZATION_DENIED"); const byId = useMemo(() => identityMap(identities), [identities]); const timeline = deniedEvents.slice(0, 6).map((ev, i) => ({ key: ev.id ?? String(i), time: formatClock(ev.timestamp), label: ev.action.replace(/_/g, " "), sub: [ev.resourceId ?? ev.resourceType, byId.get(ev.actorIdentityId ?? "")?.displayName ?? "unattributed"].filter(Boolean).join(" / "), tone: decisionTone(ev.decision) })); return <div className="special-page"><div className="special-heading"><div><Eyebrow>SECURITY / INVESTIGATION WORKSPACE</Eyebrow><h1>Security Intelligence</h1><p>Detect what policy cannot describe. Keep authorization deterministic.</p></div><Status tone="amber">RULE ENGINE · ADVISORY ONLY</Status></div><div className="intel-top"><Metric label="TRUST POSTURE" value={alertsLoading ? "…" : String(Math.max(0, 100 - (metrics.openCount + metrics.investigatingCount) * 5))} sub="COMPOSITE POSTURE SCORE" tone="mint" /><Metric label="RISK SCORE" value={alertsLoading ? "…" : riskValue} sub={metrics.maxRisk !== null ? metrics.maxRisk >= 70 ? "SEVERE" : metrics.maxRisk >= 40 ? "ELEVATED" : "NOMINAL" : live ? "NO OPEN SIGNALS" : "NO SIGNALS YET"} tone={riskTone} /><Metric label="ANOMALIES" value={alertsLoading ? "…" : String(alerts?.length ?? 0).padStart(2, "0")} sub={live ? "FROM ALERT REGISTRY" : "RUN A SCAN"} /><Metric label="BLOCKED OPERATIONS" value={alertsLoading ? "…" : String(deniedEvents.length).padStart(2, "0")} sub={deniedEvents.length ? "REAL AUTHORIZATION DENIALS" : "NONE RECORDED"} tone={deniedEvents.length ? "amber" : "mint"} /></div><div className="investigation-grid"><section className="workspace-panel"><PanelHead eyebrow={timeline.length ? "BEHAVIOURAL TIMELINE / REAL DENIALS" : "BEHAVIOURAL TIMELINE"} title="Authorization denial timeline" /><div className="investigation-timeline">{timeline.length ? timeline.map(t => <div key={t.key}><time>{t.time}</time><i className={t.tone} /><div><b>{t.label}</b><small>{t.sub}</small></div></div>) : <p className="panel-note">No authorization denials recorded yet. Denied operations (e.g. an Auditor transfer attempt) appear here in real time.</p>}</div></section><section className="workspace-panel explanation"><PanelHead eyebrow="RULES-FIRST ENGINE" title="Why signals are raised" /><p>Signals derive from REAL audit events: R1 repeated authorization denials (≥3 per actor), R2 activity from revoked/suspended identities, R3 blockchain submission failures. Nothing is fabricated and nothing overrides authorization.</p><div className="signal-tags">{deniedEvents.length >= 3 && <Status tone="red">REPEATED FAILURES</Status>}{metrics.highRiskIdentities > 0 && <Status tone="red">REVOKED-IDENTITY ACTIVITY</Status>}{alerts?.some(a => a.title.includes("Blockchain")) && <Status tone="amber">CHAIN FAILURES</Status>}{deniedEvents.length === 0 && <Status tone="mint">NO ACTIVE SIGNALS</Status>}</div><div className="advisory-note"><ShieldAlert size={18} /><span><b>ADVISORY ONLY</b> These signals never authorize or block a transaction. The policy engine and smart contracts remain the only decision-makers.</span></div><Action kind="solid" disabled={scan.isPending || !user} onClick={() => scan.mutate()} title={user ? "Run the advisory rule scan over real audit events" : "Sign in to run the scan"}>{scan.isPending ? "SCANNING…" : "RUN ADVISORY SCAN"} <ArrowRight size={15} /></Action>{!user && <p className="panel-note">Sign in to run scans against the live audit stream.</p>}</section></div></div>; }
function Metric({ label, value, sub, tone = "mint" }: { label: string; value: string; sub: string; tone?: Tone }) { return <div className="mini-metric"><span>{label}</span><strong className={tone}>{value}</strong><small><i className={tone} />{sub}</small></div>; }
function AlertPage() { const { data: alerts, isLoading: alertsLoading, error: alertsError } = useSecurityAlerts(); const { data: events } = useAuditEvents(); const { data: identities } = useIdentities(); const utils = trpc.useUtils(); const openCount = alerts?.filter(alert => alert.status === "OPEN").length ?? 0; const alert = useMemo(() => primaryAlert(alerts), [alerts]); const byId = useMemo(() => identityMap(identities), [identities]); const actor = alert?.identityId ? byId.get(alert.identityId) : undefined; const eventChain = useMemo(() => (events ?? []).filter(event => !alert?.identityId || event.actorIdentityId === alert.identityId).slice(0, 6), [events, alert]); const statusMutation = trpc.alerts.setStatus.useMutation({ onSuccess: updated => { void utils.alerts.invalidate(); void utils.audit.invalidate(); toast.success("Alert status updated", { description: `Advisory alert marked ${updated.status}. This never affects authorization.` }) }, onError: error => toast.error("Alert update failed", { description: error.message }) }); const chainRows = eventChain.length ? eventChain.map((event, index) => ({ key: event.id ?? `chain-${index}`, label: event.action.replace(/_/g, " "), sub: [event.resourceId ?? event.resourceType, decisionLabel(event.decision)].filter(Boolean).join(" / "), time: formatClock(event.timestamp), tone: decisionTone(event.decision) })) : []; return <div className="special-page"><div className="special-heading"><div><Eyebrow>SECURITY / ALERT INVESTIGATION</Eyebrow><h1>Alerts</h1><p>Investigate risk with the full chain of identity, action, asset, and evidence.</p></div><Status tone={alertsLoading ? "muted" : openCount ? "red" : "mint"}>{alertsLoading ? "SYNCING…" : openCount ? `${String(openCount).padStart(2, "0")} ACTIVE` : "NO ACTIVE ALERTS"}</Status></div>{alertsLoading && !alert ? <div className="alert-layout"><section className="alert-hero row-loading"><div className="alert-severity"><ShieldAlert size={22} /><span>SYNCING…</span></div><Eyebrow>ALERT REGISTRY / LIVE</Eyebrow><h2>Retrieving alert registry…</h2><div className="alert-context"><span>RISK<strong>—</strong></span><span>ACTOR<code>—</code></span><span>ASSET<strong>—</strong></span></div></section><section className="workspace-panel"><PanelHead eyebrow="EVENT CHAIN" title="What happened?" /><div className="alert-timeline"><div><span className="mint" /><div><b>Syncing evidence…</b><small>awaiting backend</small></div><time>—</time></div></div></section></div> : !alert ? <div className="alert-layout"><section className="alert-hero"><div className="alert-severity"><ShieldCheck size={22} /><span>FABRIC QUIET</span></div><Eyebrow>ALERT REGISTRY / {alertsError ? "UNAVAILABLE" : "EMPTY"}</Eyebrow><h2>No alerts on record.</h2><div className="alert-context"><span>RISK<strong>0</strong></span><span>OPEN<strong>0</strong></span><span>STATUS<strong className="ok">NOMINAL</strong></span></div>{!!alertsError && <p className="panel-note" role="alert">Alert registry unavailable ({String((alertsError as { message?: string }).message ?? "network error")}). The workspace remains operational.</p>}</section><section className="workspace-panel"><PanelHead eyebrow="EVENT CHAIN" title="What happened?" /><div className="alert-timeline"><div><span className="mint" /><div><b>Registry sync</b><small>no elevated signals recorded</small></div><time>—</time></div></div></section></div> : <div className="alert-layout"><section className="alert-hero"><div className="alert-severity"><ShieldAlert size={22} /><span>{alert.severity} RISK</span></div><Eyebrow>ALERT / {formatTimestamp(alert.createdAt)}</Eyebrow><h2>{alert.title}</h2><div className="alert-context"><span>RISK<strong>{alert.riskScore ?? "—"}</strong></span><span>ACTOR<code>{actor ? shortDid(actor.did) : "—"}</code></span><span>STATUS<strong>{alert.status}</strong></span></div><p className="panel-note">{alert.description}</p><div className="alert-actions"><Action kind="solid" disabled={statusMutation.isPending} onClick={() => statusMutation.mutate({ alertId: alert.id, status: "INVESTIGATING" })}>{statusMutation.isPending ? "UPDATING…" : alert.status === "OPEN" ? "Begin investigation" : "Mark INVESTIGATING"} <ArrowRight size={15} /></Action><Action disabled={statusMutation.isPending} onClick={() => statusMutation.mutate({ alertId: alert.id, status: "RESOLVED" })}>Resolve (advisory)</Action></div></section><section className="workspace-panel"><PanelHead eyebrow={eventChain.length ? "EVENT CHAIN / LIVE EVIDENCE" : "EVENT CHAIN"} title="What happened?" /><div className="alert-timeline">{chainRows.length ? chainRows.map(row => <div key={row.key}><span className={row.tone} /><div><b>{row.label}</b><small>{row.sub}</small></div><time>{row.time}</time></div>) : <p className="panel-note">No linked audit events for this alert's actor yet.</p>}</div></section></div>}</div>; }
function AdministrationPage() { const { user } = useAuth(); const { data: rolesCatalog, isLoading: rolesLoading } = trpc.identities.roles.useQuery(undefined, { enabled: !!user, retry: 1 }); const { data: identities } = useIdentities(); const { data: alerts } = useSecurityAlerts(); const isAdmin = user?.role === "admin"; return <div className="special-page"><div className="special-heading"><div><Eyebrow>GOVERNANCE / CONTROL PLANE</Eyebrow><h1>Administration</h1><p>Role catalog, permission matrix, and alert governance — all server-side.</p></div><Status>{isAdmin ? "ADMIN SESSION" : "READ-ONLY / SIGN IN AS ADMIN"}</Status></div>
    {!user && <p className="panel-note" role="alert">Sign in to load the live governance catalog. Unauthenticated visitors see no governance data.</p>}
    {rolesLoading && <div className="module-record row-loading">SYNCING ROLE CATALOG…</div>}
    {rolesCatalog && <div className="evidence-block"><h4>ROLE / PERMISSION MATRIX (FROM DATABASE)</h4><div className="sampraan-table-wrap"><table className="sampraan-table"><thead><tr><th>ROLE</th><th>PERMISSIONS</th><th>ASSIGNED IDENTITIES</th></tr></thead><tbody>{rolesCatalog.map(role => <tr key={role.id}><td><span className="role-chip">{role.name}</span></td><td>{(role.permissions ?? []).map(p => <code key={p} style={{ display: "inline-block", margin: "1px 6px 1px 0" }}>{p}</code>)}</td><td>{identities?.filter(i => i.roles?.includes(role.name)).length ?? 0}</td></tr>)}</tbody></table></div><p className="panel-note">Roles are assigned from the Identity page (RBAC administration dialog) by a platform admin; every change is audited and effective on the next operation.</p></div>}
    {alerts && <div className="evidence-block" style={{ marginTop: 18 }}><h4>ADVISORY ALERT GOVERNANCE</h4><div className="sampraan-table-wrap"><table className="sampraan-table"><thead><tr><th>ALERT</th><th>SEVERITY</th><th>RISK</th><th>STATUS</th></tr></thead><tbody>{alerts.slice(0, 6).map(a => <tr key={a.id}><td>{a.title}</td><td><Status tone={severityTone(a.severity)}>{a.severity}</Status></td><td>{a.riskScore ?? "—"}</td><td><Status tone={alertStatusTone(a.status)}>{a.status}</Status></td></tr>)}{alerts.length === 0 && <tr><td colSpan={4}>No advisory alerts recorded.</td></tr>}</tbody></table></div><p className="panel-note">Alerts are advisory only — they never participate in authorization. Manage individual alerts from the Alerts page.</p></div>}
  </div>; }
function SettingsPage() { const { data: chain } = useBlockchainStatus(); const { user } = useAuth(); return <div className="special-page"><div className="special-heading"><div><Eyebrow>GOVERNANCE / SETTINGS</Eyebrow><h1>Settings</h1><p>Network, contract, and session configuration — read-only surfaces of real state.</p></div><Status>{chain?.connected ? "NETWORK HEALTHY" : "NETWORK OFFLINE"}</Status></div><div className="evidence-block"><h4>BESU QBFT NETWORK</h4><div className="decision-proof"><div><span>NETWORK</span><code>{chain?.network ?? "—"}</code></div><div><span>CHAIN ID</span><code>{chain?.chainId ?? "—"} (mismatch refuses contract binding)</code></div><div><span>LATEST BLOCK</span><code>{chain?.latestBlock?.toLocaleString() ?? "—"}</code></div><div><span>NODE</span><code>{chain?.nodeVersion ?? "—"}</code></div><div><span>MODE</span><code>{chain?.mode ?? "—"} — contract calls are enforced on-chain</code></div></div></div><div className="evidence-block" style={{ marginTop: 16 }}><h4>SESSION</h4><div className="decision-proof"><div><span>OPERATOR</span><code>{user?.name ?? user?.email ?? "unauthenticated"}</code></div><div><span>PLATFORM ROLE</span><code>{user?.role ?? "—"}</code></div><div><span>SESSION</span><code>httpOnly cookie · server-side tracked · revocable</code></div><div><span>AUTH MODE</span><code>local password (scrypt) · OAuth preserved for production</code></div></div></div></div>; }
function GenericPage({ page }: { page: string }) { return page === "Administration" ? <AdministrationPage /> : page === "Settings" ? <SettingsPage /> : <div className="special-page"><div className="special-heading"><div><Eyebrow>GOVERNANCE / CONTROL PLANE</Eyebrow><h1>{page}</h1><p>Review and control SAMPRAAN trust operations with explicit evidence.</p></div><Status>MODULE READY</Status></div><div className="generic-module"><div className="module-visual"><Network size={28} /><Eyebrow>OPERATIONAL MODULE</Eyebrow><h2>{page} controls are active.</h2><p>Every action is scoped to an identity, evaluated against policy, and available as evidence.</p></div><div className="module-records"><PanelHead eyebrow="LIVE INDEX" title="Recent controlled events" />{["Identity proof refreshed", "Policy conditions evaluated", "Asset integrity verified", "Evidence hash anchored"].map((x, i) => <div className="module-record" key={x}><span>0{i + 1}</span><b>{x}</b><Status>RECORDED</Status><ChevronRight size={14} /></div>)}</div></div></div>; }
function Workspace() { const [page, setPage] = useState("Overview"); const [mobileOpen, setMobileOpen] = useState(false); const content = page === "Overview" ? <CommandCenter /> : page === "Identity" ? <IdentityPage /> : page === "Access Control" ? <AccessPage /> : page === "Assets" ? <AssetsPage /> : page === "Audit Evidence" ? <AuditPage /> : page === "Intelligence" ? <IntelligencePage /> : page === "Alerts" ? <AlertPage /> : <GenericPage page={page} />; return <div className="workspace"><UtilityBar /><GovHeader page={page} setPage={setPage} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} /><div className="workspace-main"><main className="workspace-content" id="workspace-main">{content}</main></div></div>; }
function AuthGate({ onSuccess, onBack }: { onSuccess: () => void; onBack: () => void }) { const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [formError, setFormError] = useState<string | null>(null); const { user, isAuthenticated, refetch } = useAuth(); const utils = trpc.useUtils(); const { data: authConfig } = trpc.auth.config.useQuery(undefined, { retry: false }); const oauthConfigured = authConfig?.oauthConfigured ?? false; const login = trpc.auth.login.useMutation({ onSuccess: result => { setFormError(null); toast.success("Signed in", { description: `Welcome, ${result.user.name ?? result.user.email} — role ${result.user.role === "admin" ? "ADMIN" : "USER"}.` }); void refetch(); void utils.identities.invalidate(); void utils.assets.invalidate(); void utils.audit.invalidate(); void utils.observatory.invalidate(); onSuccess(); }, onError: error => { const message = error.message || "Authentication failed"; setFormError(message); toast.error("Sign in failed", { description: message }); } }); const submit = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); if (login.isPending) return; const trimmed = email.trim(); if (!trimmed) { setFormError("Email is required"); return } if (!password) { setFormError("Password is required"); return } setFormError(null); login.mutate({ email: trimmed, password }) }; const useSecureIdentity = () => { if (isAuthenticated) { toast.success("Session active", { description: `Signed in as ${user?.name ?? user?.email ?? "operator"}. Entering the secure workspace.` }); onSuccess(); return } if (oauthConfigured) { toast.info("Redirecting to identity provider", { description: "Complete the cryptographic sign-in, then return to the workspace." }); return } toast.info("Email sign-in required", { description: "Sign in with your SAMPRAAN account credentials below." }) }; return <div className="auth-gate-page"><UtilityBar /><div className="auth-split">
  <section className="auth-brand"><div className="auth-brand-inner"><header><Wordmark /></header><div className="auth-brand-copy"><Eyebrow>SAMPRAAN / SECURE ACCESS</Eyebrow><h2>Institutional identity,<br /><em>verified at the gate.</em></h2><p>Roles and permissions are resolved from your account on every request — never from this browser.</p></div><ul className="auth-brand-points"><li><Fingerprint size={16} /><span>DID-linked enterprise identity</span></li><li><LockKeyhole size={16} /><span>RBAC evaluated server-side</span></li><li><FileCheck2 size={16} /><span>Every operation anchored as evidence</span></li></ul><footer><span>PERMISSIONED · VERIFIABLE · ACCOUNTABLE</span></footer></div></section>
  <section className="auth-panel"><div className="auth-card"><div className="auth-mark"><Mark /></div><div className="auth-copy"><h1>Sign in to SAMPRAAN</h1><p>Authenticate your enterprise identity securely.</p></div>{isAuthenticated && <button className="auth-identity-button" type="button" onClick={useSecureIdentity} aria-label={`Continue as ${user?.name ?? user?.email ?? "operator"}`}><Fingerprint size={17} /><span><b>{`Continue as ${user?.name ?? user?.email ?? "operator"}`}</b><small>Session verified / recommended</small></span><ArrowRight size={15} /></button>}{oauthConfigured && !isAuthenticated && <button className="auth-identity-button" type="button" onClick={useSecureIdentity}><Fingerprint size={17} /><span><b>DID Authentication</b><small>Managed identity provider / recommended</small></span><ArrowRight size={15} /></button>}<form className="auth-form" onSubmit={submit} noValidate><div className="sampraan-field"><label className="sampraan-label" htmlFor="sampraan-email">EMAIL / IDENTITY</label><input id="sampraan-email" name="email" type="email" placeholder="operator@sampraan.dev" autoComplete="email" value={email} onChange={e => { setEmail(e.target.value); setFormError(null) }} aria-invalid={!!formError || undefined} required /></div><div className="sampraan-field"><label className="sampraan-label" htmlFor="sampraan-password">PASSWORD</label><input id="sampraan-password" name="password" type="password" placeholder="••••••••••••" autoComplete="current-password" value={password} onChange={e => { setPassword(e.target.value); setFormError(null) }} aria-invalid={!!formError || undefined} required /></div>{formError && <p className="sampraan-field-error" role="alert">{formError}</p>}<Action kind="solid" type="submit" disabled={login.isPending}>{login.isPending ? "VERIFYING IDENTITY…" : "Sign In →"} </Action></form><p className="auth-security-note"><LockKeyhole size={13} /> Protected by cryptographic identity verification</p><p className="auth-legal">Sessions are httpOnly, server-tracked, and revocable. Login attempts are audited. By proceeding you acknowledge the <a href="#terms" onClick={e => { e.preventDefault(); toast.info("Terms of operation", { description: "Permissioned access is governed by organization policy." }) }}>terms of operation</a>.</p><div className="auth-proof-row"><Status>FABRIC ONLINE</Status><span>QBFT / 4 VALIDATORS</span><span>SCRYPT / SERVER-SIDE</span></div></div><button className="auth-back" onClick={onBack}><ArrowDown size={14} /> BACK TO OVERVIEW</button></section></div></div>; }
export default function Home() { const [view, setView] = useState<"landing" | "auth" | "workspace">(() => { const preview = new URLSearchParams(window.location.search).get("view"); return preview === "auth" || preview === "workspace" ? preview : "landing" }); return view === "workspace" ? <Workspace /> : view === "auth" ? <AuthGate onSuccess={() => setView("workspace")} onBack={() => setView("landing")} /> : <Landing enter={() => setView("auth")} />; }
